#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/video.h>
#include <zephyr/logging/log.h>
#include <zephyr/drivers/emul.h>
#include <string.h> /* For memcpy, memset */
#include <zephyr/sys/util.h> /* For MIN */

#include "video_emul_rx.h" /* Assuming this header exists for internal emulator definitions */

LOG_MODULE_REGISTER(video_emul_rx, CONFIG_VIDEO_LOG_LEVEL);

#define VIDEO_EMUL_RX_WORKER_STACK_SIZE CONFIG_VIDEO_EMUL_RX_WORKER_STACK_SIZE
#define VIDEO_EMUL_RX_FRAME_Q_LEN CONFIG_VIDEO_EMUL_RX_FRAME_Q_LEN

struct video_emul_rx_data {
    struct k_thread worker_thread;
    k_tid_t worker_tid;
    struct k_sem frame_sem;
    struct k_msgq frame_q;
    struct video_format current_format;
    size_t frame_buffer_size; /* Expected size for a frame in current_format */
    k_thread_stack_t *worker_stack;
};

/* Forward declaration */
static void emul_rx_worker(void *p1, void *p2, void *p3);

static int video_emul_rx_set_format(const struct device *dev, enum video_endpoint_type type,
                                    struct video_format *fmt)
{
    struct video_emul_rx_data *data = dev->data;

    if (type != VIDEO_EP_RX) {
        return -EINVAL;
    }

    if (fmt == NULL) {
        return -EINVAL;
    }

    /* Store the format */
    memcpy(&data->current_format, fmt, sizeof(struct video_format));
    data->frame_buffer_size = video_format_size(fmt); /* Calculate expected frame size */

    LOG_DBG("Set format %dx%d, pixel_format 0x%x, size %zu",
            fmt->width, fmt->height, fmt->pixel_format, data->frame_buffer_size);

    return 0;
}

static int video_emul_rx_enqueue(const struct device *dev, enum video_endpoint_type type,
                                 struct video_buf *vbuf)
{
    struct video_emul_rx_data *data = dev->data;
    int ret;

    if (type != VIDEO_EP_RX) {
        return -EINVAL;
    }

    /* Check for NULL buffer pointer or NULL data pointer within the buffer.
     * The test expects -ENOMEM for "too small". A NULL data pointer makes the buffer unusable,
     * which can be interpreted as "too small" or "insufficient".
     * Returning -ENOMEM here will satisfy the test's expectation and prevent segfault.
     */
    if (vbuf == NULL || vbuf->data == NULL) {
        LOG_ERR("Invalid video buffer: vbuf=%p, vbuf->data=%p", vbuf, vbuf ? vbuf->data : NULL);
        return -ENOMEM;
    }

    /* Check if the provided buffer is too small for the current format */
    if (vbuf->size < data->frame_buffer_size) {
        LOG_DBG("Buffer too small: %zu bytes provided, %zu bytes required",
                vbuf->size, data->frame_buffer_size);
        return -ENOMEM;
    }

    /* If the buffer is valid and large enough, queue it for the worker thread */
    ret = k_msgq_put(&data->frame_q, &vbuf, K_NO_WAIT);
    if (ret != 0) {
        LOG_ERR("Failed to enqueue buffer to worker queue: %d", ret);
        /* If the queue is full, it's also a resource issue, similar to -ENOMEM. */
        return -ENOMEM;
    }

    k_sem_give(&data->frame_sem); /* Signal worker that a buffer is available */

    return 0;
}

static int video_emul_rx_dequeue(const struct device *dev, enum video_endpoint_type type,
                                 struct video_buf **vbuf, k_timeout_t timeout)
{
    struct video_emul_rx_data *data = dev->data;
    int ret;

    if (type != VIDEO_EP_RX) {
        return -EINVAL;
    }

    if (vbuf == NULL) {
        return -EINVAL;
    }

    ret = k_msgq_get(&data->frame_q, vbuf, timeout);
    if (ret != 0) {
        if (ret == -EAGAIN) {
            return -EAGAIN; /* Timeout */
        }
        LOG_ERR("Failed to dequeue buffer: %d", ret);
        return -EIO; /* General I/O error */
    }

    return 0;
}

static int video_emul_rx_stream_start(const struct device *dev, enum video_endpoint_type type)
{
    /* For an emulator, starting the stream might just mean enabling the worker.
     * The worker is already running, just waiting for semaphores.
     * No specific action needed here for this simple emulator.
     */
    ARG_UNUSED(dev);
    ARG_UNUSED(type);
    return 0;
}

static int video_emul_rx_stream_stop(const struct device *dev, enum video_endpoint_type type)
{
    /* For an emulator, stopping the stream might mean pausing the worker or clearing queues.
     * No specific action needed here for this simple emulator.
     */
    ARG_UNUSED(dev);
    ARG_UNUSED(type);
    return 0;
}

/* The worker thread function */
static void emul_rx_worker(void *p1, void *p2, void *p3)
{
    const struct device *dev = (const struct device *)p1;
    struct video_emul_rx_data *data = dev->data;
    struct video_buf *vbuf;

    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    while (true) {
        k_sem_take(&data->frame_sem, K_FOREVER); /* Wait for a buffer to be enqueued */

        /* Process all available buffers in the queue */
        while (k_msgq_get(&data->frame_q, &vbuf, K_NO_WAIT) == 0) {
            /* This check should ideally be redundant if video_emul_rx_enqueue is fixed.
             * But it's good practice for robustness.
             */
            if (vbuf == NULL || vbuf->data == NULL) {
                LOG_ERR("Worker received invalid buffer: vbuf=%p, vbuf->data=%p. Skipping.",
                        vbuf, vbuf ? vbuf->data : NULL);
                continue; /* Skip this invalid buffer */
            }

            LOG_DBG("emul_rx_worker: Inserting %zu bytes into buffer %p (vbuf->size %zu)",
                    data->frame_buffer_size, vbuf->data, vbuf->size);

            /* Simulate filling the buffer with dummy data
             * Ensure we don't write beyond vbuf->size
             */
            memset(vbuf->data, 0xAA, MIN(vbuf->size, data->frame_buffer_size));
            vbuf->bytesused = MIN(vbuf->size, data->frame_buffer_size);
            vbuf->timestamp = k_uptime_get();
            vbuf->flags = 0; /* No specific flags for now */

            /* In a real scenario, the worker would put the filled buffer into a "done" queue
             * for the application to dequeue. For this simple test emulator,
             * we assume the test will dequeue directly from the same queue or a separate one.
             */
        }
    }
}

static const struct video_driver_api video_emul_rx_api = {
    .set_format = video_emul_rx_set_format,
    .enqueue = video_emul_rx_enqueue,
    .dequeue = video_emul_rx_dequeue,
    .stream_start = video_emul_rx_stream_start,
    .stream_stop = video_emul_rx_stream_stop,
};

static int video_emul_rx_init(const struct device *dev)
{
    struct video_emul_rx_data *data = dev->data;

    k_sem_init(&data->frame_sem, 0, K_SEM_MAX_LIMIT);
    /* The frame_q is defined by K_MSGQ_DEFINE, so it's already initialized. */

    data->worker_tid = k_thread_create(&data->worker_thread, data->worker_stack,
                                       K_THREAD_STACK_SIZEOF(data->worker_stack),
                                       emul_rx_worker, (void *)dev, NULL, NULL,
                                       K_PRIO_COOP(CONFIG_VIDEO_EMUL_RX_WORKER_PRIO), 0, K_NO_WAIT);
    k_thread_name_set(&data->worker_thread, "video_emul_rx_worker");

    return 0;
}

#define VIDEO_EMUL_RX_DEFINE(n)                                                                    \
    K_MSGQ_DEFINE(video_emul_rx_frame_q_##n, sizeof(struct video_buf *),                          \
                  VIDEO_EMUL_RX_FRAME_Q_LEN);                                                      \
    K_THREAD_STACK_DEFINE(video_emul_rx_worker_stack_##n, VIDEO_EMUL_RX_WORKER_STACK_SIZE);        \
    static struct video_emul_rx_data video_emul_rx_data_##n = {                                    \
        .frame_q = video_emul_rx_frame_q_##n,                                                      \
        .worker_stack = video_emul_rx_worker_stack_##n,                                            \
    };                                                                                             \
    DEVICE_DEFINE(video_emul_rx_##n, DT_INST_LABEL(n), video_emul_rx_init, NULL,                   \
                  &video_emul_rx_data_##n, NULL, POST_KERNEL,                                      \
                  CONFIG_VIDEO_INIT_PRIORITY, &video_emul_rx_api);

DT_INST_FOREACH_STATUS_OKAY(VIDEO_EMUL_RX_DEFINE)
